css:
:host {
  --bg-top: #0d3257;
  --bg-mid: #214463;
  --bg-bottom: #eee4d1;
  --sand: rgba(245, 236, 219, 0.96);
  --sand-strong: #f6ead4;
  --ink: #143254;
  --teal: #18b7b7;
  --gold: #c79a3e;
  --copper: #b56404;
  --mist: #dce8ee;
  --forest: #237a57;
  --orange: #ff9f43;
  --shadow: 0 18px 40px rgba(8, 18, 31, 0.18);
}

* {
  box-sizing: border-box;
}

[data-module-body] {
  margin: 0;
  font-family: "Manrope", sans-serif;
  font-size: 110%;
  background:
    radial-gradient(circle at top right, rgba(255, 255, 255, 0.12), transparent 22%),
    radial-gradient(circle at left 80%, rgba(255, 183, 77, 0.12), transparent 18%),
    linear-gradient(180deg, var(--bg-top) 0%, var(--bg-mid) 44%, var(--bg-bottom) 100%);
  color: var(--ink);
  overflow-x: hidden;
  overflow-y: hidden;
}

[data-module-body].modal-open {
  overflow: hidden;
}

.page-shell {
  height: 100dvh;
  min-height: 100dvh;
  padding: 6px;
  overflow: hidden;
}

.auth-gate {
  min-height: calc(100vh - 24px);
  min-height: calc(100dvh - 24px);
  display: grid;
  place-items: center;
}

.auth-card {
  width: min(100%, 390px);
  padding: 26px 22px;
  border-radius: 28px;
  background:
    radial-gradient(circle at top right, rgba(255, 214, 141, 0.28), transparent 32%),
    linear-gradient(180deg, rgba(248, 241, 228, 0.98) 0%, rgba(239, 226, 201, 0.98) 100%);
  border: 1px solid rgba(199, 154, 62, 0.28);
  box-shadow: 0 24px 44px rgba(8, 18, 31, 0.2);
}

.auth-card__badge,
.auth-card__title,
.auth-card__text {
  margin: 0;
  text-align: center;
}

.auth-card__badge {
  display: inline-flex;
  justify-content: center;
  width: 100%;
  margin-bottom: 12px;
  font-size: 0.72rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  color: #8c5517;
}

.auth-card__title {
  font-size: 1.5rem;
  font-weight: 900;
  letter-spacing: 0.03em;
  color: var(--ink);
}

.auth-card__text {
  margin-top: 8px;
  font-size: 0.86rem;
  line-height: 1.45;
  color: rgba(20, 50, 84, 0.8);
}

.auth-form {
  display: grid;
  gap: 10px;
  margin-top: 18px;
}

.auth-field {
  display: grid;
  gap: 6px;
}

.auth-field span {
  font-size: 0.68rem;
  font-weight: 900;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  color: rgba(20, 50, 84, 0.78);
}

.auth-field input {
  width: 100%;
  min-height: 48px;
  padding: 11px 14px;
  border: 1px solid rgba(13, 50, 87, 0.14);
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.92);
  font: inherit;
  color: var(--ink);
  text-align: center;
  letter-spacing: 0.16em;
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.82);
}

.auth-field input:focus {
  outline: 2px solid rgba(24, 183, 183, 0.24);
  border-color: rgba(24, 183, 183, 0.56);
}

.auth-status {
  margin: 0;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(255, 159, 67, 0.18);
  color: #8a4400;
  font-size: 0.72rem;
  font-weight: 800;
  text-align: center;
}

.auth-submit {
  min-height: 48px;
  border-radius: 18px;
  background: linear-gradient(180deg, #0d6380 0%, #0b4d63 100%);
  color: #ffffff;
  font-size: 0.86rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  box-shadow: 0 14px 26px rgba(11, 77, 99, 0.22);
}

.app-frame {
  width: min(100%, 430px);
  margin: 0 auto;
  display: flex;
  flex-direction: column;
  gap: 6px;
  height: calc(100dvh - 16px);
  max-height: calc(100dvh - 16px);
  overflow: hidden;
  padding-bottom: 6px;
}

.hero-card,
.panel-card,
.footer-banner {
  border-radius: 24px;
  box-shadow: var(--shadow);
}

.hero-card {
  display: grid;
  grid-template-columns: auto minmax(0, 1fr);
  align-items: center;
  gap: 12px;
  min-height: 0;
  padding: 18px 16px;
  background: linear-gradient(90deg, rgba(255, 210, 120, 0.4) 0%, rgba(232, 217, 187, 0.96) 100%);
  border: 2px solid rgba(255, 159, 67, 0.72);
  box-shadow: 0 22px 40px rgba(181, 100, 4, 0.22);
}

/* Premium 3D logo button for the title. */
.hero-logo-wrap {
  position: relative;
  overflow: hidden;
  border: 1px solid rgba(255, 255, 255, 0.95);
  background: linear-gradient(145deg, #ffffff 0%, #e8f2f7 52%, #b9d0dc 100%);
  box-shadow: 0 0 0 3px rgba(255, 255, 255, 0.48), 0 16px 28px rgba(12, 49, 72, 0.26), inset 0 2px 0 rgba(255, 255, 255, 0.98), inset 0 -8px 14px rgba(37, 78, 101, 0.14);
  transition: transform 160ms ease, filter 160ms ease, box-shadow 160ms ease;
}

.hero-logo-wrap:hover,
.hero-logo-wrap:focus-visible {
  filter: saturate(1.08);
  transform: translateY(-2px) scale(1.015);
}

.hero-logo-wrap:active {
  transform: translateY(1px) scale(0.98);
}

.hero-logo {
  position: relative;
  z-index: 1;
  filter: drop-shadow(0 8px 9px rgba(20, 52, 75, 0.2));
}

.hero-copy {
  flex: 1 1 auto;
  display: grid;
  justify-items: center;
  text-align: center;
  min-width: 0;
}

.hero-side-icon {
  width: 112px;
  height: 112px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.92);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
  box-shadow: 0 12px 24px rgba(8, 18, 31, 0.12);
  text-decoration: none;
}

.hero-side-icon:hover {
  transform: translateY(-1px) scale(1.02);
}

.hero-side-icon__image {
  width: 98px;
  height: 98px;
  object-fit: contain;
}

.hero-logo-wrap {
  position: relative;
  width: 118px;
  height: 118px;
  border-radius: 24px;
  background: rgba(255, 255, 255, 0.94);
  display: grid;
  place-items: center;
  flex: 0 0 auto;
}

.hero-logo-link {
  text-decoration: none;
}

.hero-logo-link:hover {
  transform: translateY(-1px) scale(1.01);
  box-shadow: 0 14px 28px rgba(8, 18, 31, 0.16);
}

.hero-logo {
  width: 104px;
  height: 104px;
  object-fit: contain;
}

.home-logo-label {
  position: absolute;
  z-index: 2;
  right: 8px;
  bottom: 4px;
  left: 8px;
  padding: 2px 4px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.92);
  color: #1762a1;
  font-size: 0.58rem;
  font-weight: 900;
  letter-spacing: 0.12em;
  line-height: 1.1;
  text-align: center;
}

.hero-kicker {
  display: block;
  margin: 0 auto;
  padding: 7px 14px;
  border-radius: 999px;
  background: linear-gradient(180deg, rgba(255, 248, 220, 0.98) 0%, rgba(248, 221, 152, 0.96) 100%);
  box-shadow: 0 10px 22px rgba(181, 100, 4, 0.16);
  font-size: 1rem;
  font-weight: 900;
  letter-spacing: 0.11em;
  color: rgba(125, 77, 10, 0.98);
  text-transform: uppercase;
}

.hero-copy h1 {
  margin: 10px 0 0;
  font-size: clamp(2.1rem, 7vw, 2.9rem);
  line-height: 0.9;
  font-weight: 900;
  letter-spacing: 0.08em;
  color: var(--copper);
  text-shadow: 5px 5px 10px rgba(122, 57, 0, 0.34);
}

.panel-card {
  background: var(--sand);
  border: 1px solid rgba(255, 255, 255, 0.18);
  padding: 8px;
}

.schedule-card {
  border-color: rgba(199, 154, 62, 0.46);
  overflow: hidden;
}

.records-card {
  position: relative;
  display: grid;
  gap: 8px;
  border-color: rgba(199, 154, 62, 0.34);
  background:
    linear-gradient(180deg, rgba(249, 244, 233, 0.98) 0%, rgba(240, 230, 210, 0.96) 100%);
  box-shadow: 0 18px 36px rgba(103, 67, 15, 0.14);
}

.records-panel-toggle {
  position: relative;
  width: 100%;
  min-height: 54px;
  padding: 13px 16px;
  border: 1px solid rgba(145, 88, 18, 0.18);
  border-radius: 20px;
  background:
    radial-gradient(circle at top left, rgba(255, 227, 174, 0.5), transparent 34%),
    radial-gradient(circle at bottom right, rgba(16, 111, 137, 0.16), transparent 34%),
    linear-gradient(135deg, #fff8eb 0%, #f1debd 52%, #e8c995 100%);
  box-shadow:
    0 16px 28px rgba(123, 83, 31, 0.14),
    inset 0 1px 0 rgba(255, 255, 255, 0.88);
  color: #6f4516;
  font-size: 0.86rem;
  font-weight: 900;
  letter-spacing: 0.06em;
  text-transform: uppercase;
}

.records-card {
  padding: 5px;
}

.pending-queue-status {
  margin: 0 8px 2px;
  color: #b91c1c;
  font-size: 0.74rem;
  font-weight: 900;
  letter-spacing: 0.04em;
  text-align: center;
  text-transform: uppercase;
}

.pending-queue-status[hidden] {
  display: none !important;
}

.pending-send-confirmation {
  display: grid;
  grid-template-columns: 1fr auto;
  gap: 4px 12px;
  align-items: center;
  margin: 10px 8px 2px;
  padding: 12px 14px;
  border: 1px solid rgba(22, 101, 52, 0.35);
  border-radius: 16px;
  background: linear-gradient(135deg, #dcfce7 0%, #f0fdf4 100%);
  color: #166534;
  box-shadow: 0 10px 22px rgba(22, 101, 52, 0.14);
}

.pending-send-confirmation[hidden] {
  display: none !important;
}

.pending-send-confirmation strong,
.pending-send-confirmation span {
  grid-column: 1;
}

.pending-send-confirmation strong {
  font-size: 0.9rem;
}

.pending-send-confirmation span {
  font-size: 0.8rem;
  line-height: 1.3;
}

.pending-send-confirmation button {
  grid-column: 2;
  grid-row: 1 / span 2;
  min-width: 56px;
  min-height: 42px;
  border-radius: 12px;
  background: #166534;
  color: #fff;
  font-weight: 900;
}

.records-card .records-panel-toggle {
  min-height: 46px;
  padding: 10px 14px;
}

.records-panel-toggle::after {
  content: "Abrir";
  position: absolute;
  right: 14px;
  top: 50%;
  transform: translateY(-50%);
  padding: 4px 10px;
  border-radius: 999px;
  background: rgba(255, 255, 255, 0.54);
  color: rgba(111, 69, 22, 0.88);
  font-size: 0.54rem;
  letter-spacing: 0.08em;
}

.records-panel-body {
  display: grid;
}

.records-panel-modal {
  position: fixed;
  inset: 0;
  z-index: 69;
  display: grid;
  place-items: center;
  padding: 8px;
}

.records-panel-backdrop {
  position: absolute;
  inset: 0;
  background: rgba(8, 18, 31, 0.54);
  backdrop-filter: blur(8px);
}

.records-panel-sheet {
  position: relative;
  width: min(100%, 560px);
  max-height: min(100dvh - 10px, 88vh);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto minmax(0, 1fr) auto;
  padding: 10px;
  border-radius: 24px;
  background: linear-gradient(180deg, rgba(249, 244, 233, 0.98) 0%, rgba(237, 227, 207, 0.98) 100%);
  box-shadow: 0 18px 36px rgba(8, 18, 31, 0.24);
}

.records-panel-sheet__header {
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
  margin-bottom: 8px;
}

.records-panel-sheet__header > * {
  width: 100%;
}

.records-panel-footer {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(13, 50, 87, 0.08);
}

.entry-card {
  border-color: rgba(13, 50, 87, 0.14);
}

.entry-open-button {
  width: 100%;
  margin-top: 8px;
  padding: 11px 14px;
  border-radius: 16px;
  background: linear-gradient(180deg, #0d3257 0%, #1762a1 100%);
  color: #ffffff;
  text-align: center;
  box-shadow: 0 12px 24px rgba(13, 50, 87, 0.18);
  font-size: 0.72rem;
}

.entry-modal {
  position: fixed;
  inset: 0;
  z-index: 70;
  display: grid;
  place-items: center;
  padding: 18px;
}

.entry-modal__backdrop {
  position: absolute;
  inset: 0;
  background: rgba(8, 18, 31, 0.54);
  backdrop-filter: blur(8px);
}

.entry-sheet {
  position: relative;
  width: min(100%, 430px);
  max-height: min(100dvh - 18px, 860px);
  overflow-y: auto;
  padding: 12px 12px 14px;
  border-radius: 24px;
  background: linear-gradient(180deg, rgba(249, 244, 233, 0.98) 0%, rgba(237, 227, 207, 0.98) 100%);
  box-shadow: 0 18px 36px rgba(8, 18, 31, 0.24);
}

.entry-sheet__footer {
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(13, 50, 87, 0.08);
}

.entry-sheet__back-button.records-panel-toggle {
  min-height: 40px;
  padding: 9px 12px;
  color: var(--ink);
  text-transform: none;
}

.choice-sheet {
  position: relative;
  width: min(100%, 430px);
  max-height: 82vh;
  overflow-y: auto;
  padding: 16px 14px 18px;
  border-radius: 24px;
  background: linear-gradient(180deg, rgba(249, 244, 233, 0.98) 0%, rgba(237, 227, 207, 0.98) 100%);
  box-shadow: 0 18px 36px rgba(8, 18, 31, 0.24);
}

.monthly-sheet {
  width: min(100%, 640px);
  max-height: min(100dvh - 10px, 96vh);
  overflow: hidden;
  display: grid;
  grid-template-rows: auto auto auto minmax(0, 1fr) auto;
}

.monthly-sheet__title {
  margin: 4px 0 0;
  font-size: 1rem;
  font-weight: 900;
  color: var(--ink);
  text-align: center;
}

.monthly-sheet__header-copy {
  width: 100%;
  display: grid;
  justify-items: center;
  text-align: center;
  gap: 2px;
}

.records-hero > [data-auth-user],
.monthly-sheet__header-copy > [data-auth-user] {
  color: rgba(20, 50, 84, 0.52);
  font-size: 0.67rem;
  font-weight: 700;
  line-height: 1.15;
  text-shadow: none;
}

.records-hero > [data-auth-user]::before {
  content: "Responsável pelo registro: ";
  color: rgba(20, 50, 84, 0.68);
}

.monthly-sheet__controls {
  display: grid;
  gap: 8px;
  margin-top: 6px;
}

.monthly-sheet__footer {
  display: grid;
  gap: 8px;
  margin-top: 8px;
  padding-top: 8px;
  border-top: 1px solid rgba(13, 50, 87, 0.08);
}

.monthly-sheet__share {
  margin-top: 2px;
}

.monthly-sheet__summary {
  margin: 6px 0 0;
  font-size: 0.67rem;
  font-weight: 800;
  color: rgba(20, 50, 84, 0.8);
  text-align: center;
}

.monthly-sheet__close.records-panel-toggle::after {
  content: none;
}

.monthly-records-list {
  display: grid;
  gap: 8px;
  margin-top: 8px;
  max-height: none;
  overflow-y: auto;
  padding-right: 4px;
  scrollbar-width: thin;
}

.choice-sheet__description {
  margin: 10px 0 0;
  font-size: 0.66rem;
  font-weight: 700;
  line-height: 1.4;
  color: rgba(20, 50, 84, 0.84);
}

.choice-sheet__options {
  display: grid;
  gap: 8px;
  margin-top: 12px;
}

.choice-sheet__option {
  width: 100%;
  padding: 11px 12px;
  border-radius: 16px;
  background: rgba(255, 255, 255, 0.86);
  color: var(--ink);
  text-align: left;
  box-shadow: 0 8px 18px rgba(8, 18, 31, 0.08);
  font-size: 0.68rem;
}

.entry-sheet__header {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  gap: 8px;
}

.entry-sheet__header-copy {
  width: 100%;
  display: grid;
  justify-items: center;
  gap: 3px;
  padding: 0;
  text-align: center;
}

.entry-sheet__title {
  margin: 0;
  font-size: 1rem;
  font-weight: 900;
  line-height: 1.15;
  text-transform: uppercase;
  color: var(--ink);
}

.entry-sheet__auth {
  color: rgba(20, 50, 84, 0.54);
  font-size: 0.64rem;
  font-weight: 700;
  line-height: 1.2;
}

.entry-sheet__auth::before {
  content: "Responsável pelo lançamento: ";
}

.entry-modal--editing .entry-sheet__auth::before {
  content: "Responsável pela edição: ";
}

.entry-sheet__close {
  position: absolute;
  top: 0;
  right: 0;
  padding: 8px 10px;
  border-radius: 12px;
  background: var(--mist);
  color: var(--ink);
  font-size: 0.62rem;
}

.entry-form {
  display: grid;
  grid-template-columns: 1fr;
  gap: 7px;
  margin-top: 6px;
}

.entry-actions {
  display: grid;
  gap: 6px;
  margin-top: 2px;
}

.entry-status {
  margin: 0;
  padding: 10px 12px;
  border-radius: 14px;
  background: rgba(220, 232, 238, 0.65);
  font-size: 0.64rem;
  font-weight: 800;
  line-height: 1.35;
}

.entry-status.is-error {
  background: rgba(255, 159, 67, 0.18);
  color: #8a4400;
}

.entry-status.is-success {
  background: rgba(35, 122, 87, 0.16);
  color: #17613f;
}

.entry-submit-button {
  width: 100%;
  min-height: 44px;
  padding: 10px 14px;
  border-radius: 16px;
  background: linear-gradient(180deg, #0d6380 0%, #0b4d63 100%);
  color: #ffffff;
  text-align: center;
  box-shadow: 0 12px 24px rgba(11, 77, 99, 0.18);
  font-size: 0.7rem;
}

.entry-submit-button:disabled {
  cursor: wait;
  opacity: 0.72;
}

.entry-field {
  display: grid;
  gap: 4px;
  padding: 4px;
  border-radius: 18px;
  transition:
    background-color 180ms ease,
    box-shadow 180ms ease,
    border-color 180ms ease;
}

.entry-field span {
  font-size: 0.55rem;
  font-weight: 800;
  color: rgba(20, 50, 84, 0.8);
  text-transform: uppercase;
}

.entry-field input,
.entry-field select,
.entry-field textarea {
  width: 100%;
  border: 1px solid rgba(13, 50, 87, 0.12);
  border-radius: 14px;
  min-height: 38px;
  padding: 8px 10px;
  background: rgba(255, 255, 255, 0.82);
  font: inherit;
  color: var(--ink);
  box-shadow: inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.entry-field textarea {
  resize: none;
  min-height: 38px;
}

.entry-field input:focus,
.entry-field select:focus,
.entry-field textarea:focus {
  outline: 2px solid rgba(24, 183, 183, 0.24);
  border-color: rgba(24, 183, 183, 0.56);
}

.entry-field--disabled input,
.entry-field--disabled select,
.entry-field--disabled textarea {
  background: rgba(233, 239, 244, 0.92);
  color: rgba(20, 50, 84, 0.88);
}

.entry-field--pending {
  background: rgba(255, 98, 98, 0.1);
  box-shadow: inset 0 0 0 1px rgba(196, 36, 36, 0.18);
}

.entry-field--pending input,
.entry-field--pending select,
.entry-field--pending textarea {
  background: rgba(255, 245, 245, 0.96);
  border-color: rgba(196, 36, 36, 0.4);
  box-shadow:
    0 0 0 2px rgba(196, 36, 36, 0.12),
    inset 0 1px 0 rgba(255, 255, 255, 0.72);
}

.entry-field--pending span {
  color: rgba(150, 26, 26, 0.9);
}

.entry-field--autofilled,
.entry-field--complete {
  background: rgba(67, 160, 71, 0.1);
  box-shadow: inset 0 0 0 1px rgba(53, 126, 57, 0.16);
}

.entry-field--autofilled input,
.entry-field--autofilled select,
.entry-field--autofilled textarea,
.entry-field--complete input,
.entry-field--complete select,
.entry-field--complete textarea {
  background: rgba(242, 255, 243, 0.98);
  border-color: rgba(53, 126, 57, 0.34);
  box-shadow:
    0 0 0 2px rgba(53, 126, 57, 0.1),
    inset 0 1px 0 rgba(255, 255, 255, 0.78);
}

.entry-field--autofilled span,
.entry-field--complete span {
  color: rgba(31, 102, 45, 0.92);
}

.entry-field--locked span::after {
  content: " • automatico";
  color: rgba(156, 76, 0, 0.82);
}

.entry-field select optgroup {
  font-weight: 900;
  color: rgba(13, 50, 87, 0.88);
}

.entry-field select optgroup.select-optgroup--highlight {
  color: #9b5b00;
}

.entry-field select option.select-option-highlight {
  color: #9b5b00;
  background: rgba(255, 236, 193, 0.96);
  font-weight: 800;
}

.entry-field select.select-has-highlighted-value {
  color: #9b5b00;
  background: rgba(255, 236, 193, 0.96);
  border-color: rgba(155, 91, 0, 0.3);
  font-weight: 900;
  text-transform: uppercase;
}

.search-banner {
  margin-bottom: 8px;
  padding: 8px;
  border-radius: 18px;
  background: rgba(220, 232, 238, 0.34);
  border: 1px solid rgba(13, 50, 87, 0.08);
  min-height: 0;
  display: flex;
  flex-direction: column;
  justify-content: flex-start;
  gap: 8px;
}

