.module-link-card {
  position: relative;
  isolation: isolate;
  display: grid;
  grid-template-rows: 1fr auto;
  justify-items: center;
  min-width: 0;
  min-height: 108px;
  overflow: hidden;
  padding: 5px 4px 8px;
  border: 1px solid rgba(255, 255, 255, 0.94);
  border-radius: 20px;
  background: linear-gradient(160deg, rgba(255, 255, 255, 0.98) 0%, rgba(235, 244, 248, 0.94) 48%, rgba(199, 218, 228, 0.9) 100%);
  color: #1762a1;
