  min-width: 0;
  max-width: 100%;
  flex-direction: column;
  gap: 2px;
  padding-block: 2px;
  line-height: 1;
  white-space: normal;
}

.schedule-card .sigla-token__stacked-top {
  display: block;
  flex: 0 0 auto;
  font-weight: 900;
}

.schedule-card .sigla-token__stacked-bottom {
  display: flex;
  min-width: 0;
  max-width: 100%;
  align-items: center;
  justify-content: center;
  gap: 2px;
  white-space: nowrap;
}

.schedule-card .sigla-token__stacked-bottom .dc-vacation-sigla {
  margin: 0;
  padding-inline: 2px;
}

.schedule-card .sigla-token__stacked-separator {
  flex: 0 0 auto;
  font-size: 0.82em;
  font-weight: 800;
}

/* Mantém toques rápidos como cliques, sem o zoom de duplo toque do iPhone. */
.schedule-card #prevButton,
.schedule-card #todayButton,
.schedule-card #nextButton {
  touch-action: manipulation;
  -webkit-user-select: none;
  user-select: none;
  -webkit-touch-callout: none;
}

@media (max-height: 700px) {
  .schedule-card .sigla-token {
    min-height: clamp(32px, 5dvh, 40px);
    padding-block: 4px;
  }
}
